374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
477		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
478		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
479		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
480		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
481		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
482		if len(fd.Sources) != 0 {
483			bounds := make(map[string][]occurrenceWindow, len(fd.Landmarks))
484			for _, lm := range fd.Landmarks {
485				bounds[lm.ID] = occurrenceWindowsOf(lm)
486			}
487			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
488			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
489			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
490			// 也不能按帧数猜测。
491			tallies := make(map[string]map[int]int, len(fd.Landmarks))
492			for k, src := range fd.Sources {
493				if src == nil {
494					continue // 旧地图帧：无逐帧依据，不要求补齐归属
495				}
496				t := fd.Trajectory[k+1].Time
497				for _, ob := range src.Observations {
498					wins, ok := bounds[ob.ID]
499					if !ok {
500						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
501					}
502					num := occurrenceNumberAt(wins, t)
503					if num == 0 {
504						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
505					}
506					c := tallies[ob.ID]
507					if c == nil {
508						c = make(map[int]int, 1)
509						tallies[ob.ID] = c
510					}
511					c[num]++
512				}
513			}
514			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
515			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
516			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
517			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
518			// 次数，正常校正后保存的文件仍满足此不变量。
519			for _, lm := range fd.Landmarks {
520				if len(lm.Occurrences) == 0 {
521					// 旧版平铺路标即第 1 次出现。
522					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
523						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
524					}
525					continue
526				}
527				for _, oj := range lm.Occurrences {
528					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
529						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
530					}
531				}
532			}
533	
534			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
535			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
536			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
537			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
538			// 空观测帧不增加贡献。转换、接纳、增量平均与计数全部复用导入/校正
539			// 的同一规则（见 aggregate.go），旧文件固定旧贡献（LegacyCount 次
540			// 平均）作为聚合起点——不能当成零，也不能用缺少依据的帧数代替。
541			// 回环校正后保存的文件按当前轨迹重放即得到当前位置，不要求等于校正
542			// 记录里的历史快照；各次出现分别核对，已失效的出现同样核对。合并
543			// 距离只是导入/校正时的接纳门槛，不是保存位置偏差的容许范围：重放
544			// 中出现非有限结果或距离冲突，或最终平均位置与保存位置不完全一致，
545			// 都按损坏拒绝。纯旧文件没有 sources、null 旧帧没有依据，均不重放。
546			type posKey struct {
547				id  string
548				num int
549			}
550			posAggs := make(map[posKey]*observationAgg, len(fd.Landmarks))
551			seedPosAgg := func(id string, num, legacyCount int, lx, ly float64) {
552				a := &observationAgg{}
553				if legacyCount > 0 {
554					a.seed(legacyCount, lx, ly)
555				}
556				posAggs[posKey{id: id, num: num}] = a
557			}
558			for _, lm := range fd.Landmarks {
559				if len(lm.Occurrences) == 0 {
560					// 旧版平铺路标即第 1 次出现。
561					seedPosAgg(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
562					continue
563				}
564				for _, oj := range lm.Occurrences {
565					seedPosAgg(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
566				}
567			}
568			for k, src := range fd.Sources {
569				if src == nil {
570					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
571				}
572				pose := fd.Trajectory[k+1]
573				for _, ob := range src.Observations {
574					// 归属（存在性与时间边界）已在上面校验，num 必非 0。
575					num := occurrenceNumberAt(bounds[ob.ID], pose.Time)
576					a := posAggs[posKey{id: ob.ID, num: num}]
577					switch a.admit(pose, ob, fd.Config.MergeDistance) {
578					case obsNonFinite:
579						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, ob.ID, num, pose.Time)
580					case obsConflict:
581						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, ob.ID, num, pose.Time)
582					}
583				}
584			}
585			checkPosition := func(id string, num int, x, y float64) error {
586				a := posAggs[posKey{id: id, num: num}]
587				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
588				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
589				if a.x != x || a.y != y {
590					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
591				}
592				return nil
593			}
594			for _, lm := range fd.Landmarks {
595				if len(lm.Occurrences) == 0 {
596					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
597						return err
598					}
599					continue
600				}
601				for _, oj := range lm.Occurrences {
602					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
603						return err
604					}
605				}
606			}
607		}
608		segIDs := make(map[string]struct{}, len(fd.Segments))
609		for _, sg := range fd.Segments {
610			if sg.ID == "" || sg.Hash == "" {
611				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
612			}
613			if _, dup := segIDs[sg.ID]; dup {
614				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
615			}
616			segIDs[sg.ID] = struct{}{}
617		}
618		corrIDs := make(map[string]struct{}, len(fd.Corrections))
619		for _, cr := range fd.Corrections {
620			if cr.ID == "" || cr.Anchor > cr.EndTime {
621				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
622			}
623			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
624			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
625			// 校验为严格递增，命中即唯一。
626			anchorIdx, endIdx := -1, -1
627			for j := 1; j < len(fd.Trajectory); j++ {
628				if fd.Trajectory[j].Time == cr.Anchor {
629					anchorIdx = j
630				}
631				if fd.Trajectory[j].Time == cr.EndTime {
632					endIdx = j
633				}
634			}
635			if anchorIdx < 0 || endIdx < 0 {
636				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
637			}
638			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
639			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
640			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
641			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
642			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
643			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
644			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
645			if len(cr.Poses) != endIdx-anchorIdx+1 {
646				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
647			}
648			for i, pc := range cr.Poses {
649				ft := fd.Trajectory[anchorIdx+i].Time
650				if pc.Before.Time != ft || pc.After.Time != ft {
651					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
652				}
653				if !finitePose(pc.Before) || !finitePose(pc.After) {
654					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
655				}
656			}
657			for _, lc := range cr.Landmarks {
658				if lc.ID == "" {
659					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
660				}
661				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
662					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
663					lc.Before.Count < 1 || lc.After.Count < 1 {
664					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
665				}
666			}
667			if _, dup := corrIDs[cr.ID]; dup {
668				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
669			}
670			corrIDs[cr.ID] = struct{}{}
671		}
672		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
673		for _, iv := range fd.Invalidations {
674			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
675				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
676			}
677			if _, dup := invalIDs[iv.ID]; dup {
678				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
679			}
680			invalIDs[iv.ID] = struct{}{}
681			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
682			for _, l := range iv.Landmarks {
683				if l.ID == "" || l.Occurrence < 1 {
684					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
685				}
686				if _, dup := lmSeen[l.ID]; dup {
687					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
688				}
689				lmSeen[l.ID] = struct{}{}
690			}
691		}
692		return nil
693	}
694	
695	func finitePose(p Pose) bool {
696		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
697	}
698	
699	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
700	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
701	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
702		h := sha256.New()
703		var b [8]byte
704		binary.BigEndian.PutUint64(b[:], uint64(anchor))
705		h.Write(b[:])
706		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
707			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
708			h.Write(b[:])
709		}
710		return fmt.Sprintf("%x", h.Sum(nil))
711	}
712	
713	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
714	func (m *Map) saveExclusive() error {
715		data, err := encodeFile(m.state)
716		if err != nil {
717			return err
718		}
719		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
720		if err != nil {
721			return err
722		}
723		return writeAndClose(f, data, m.path)
724	}
725	
726	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
727	func (m *Map) saveReplace() (err error) {
728		data, err := encodeFile(m.state)
729		if err != nil {
730			return err
731		}
732		dir, base := filepath.Split(m.path)
733		if dir == "" {
734			dir = "."
735		}
736		f, err := os.CreateTemp(dir, base+".tmp-*")
737		if err != nil {
738			return err
739		}
740		tmpName := f.Name()
741		// 任何失败路径都尽力清理临时文件。
742		defer func() {
743			if err != nil {
744				_ = os.Remove(tmpName)
745			}
746		}()
747		if err = writeAndClose(f, data, tmpName); err != nil {
748			return err
749		}
750		if err = os.Rename(tmpName, m.path); err != nil {
751			return err
752		}
753		return nil
754	}
755	
756	func writeAndClose(f *os.File, data []byte, name string) (err error) {
757		defer func() {
758			if cerr := f.Close(); err == nil {
759				err = cerr
760			}
761		}()
762		if _, err = f.Write(data); err != nil {
763			return err
764		}
765		if err = f.Sync(); err != nil {
766			return err
767		}
768		return nil
769	}
770	
771	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
772	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
773	func canonicalHash(frames []Frame) string {
774		h := sha256.New()
775		var lenBuf [4]byte
776		var numBuf [8]byte
777		putU32 := func(v uint32) {
778			binary.BigEndian.PutUint32(lenBuf[:], v)
779			h.Write(lenBuf[:])
780		}
781		putU64 := func(v uint64) {
782			binary.BigEndian.PutUint64(numBuf[:], v)
783			h.Write(numBuf[:])
784		}
785		putStr := func(s string) {
786			putU32(uint32(len(s)))
787			h.Write([]byte(s))
788		}
789	
790		putU32(uint32(len(frames)))
791		for _, fr := range frames {
792			putU64(uint64(fr.Time))
793			putU64(math.Float64bits(fr.DX))
794			putU64(math.Float64bits(fr.DY))
795			putU64(math.Float64bits(fr.DHeading))
796			putU64(math.Float64bits(fr.MoveVariance))
797			putU32(uint32(len(fr.Observations)))
798			for _, ob := range fr.Observations {
799				putStr(ob.ID)
800				putU64(math.Float64bits(ob.X))
801				putU64(math.Float64bits(ob.Y))
802			}
803		}
804		return fmt.Sprintf("%x", h.Sum(nil))
805	}
806

