// writeLegacyV1File 用当前状态构造一个去掉 sources/corrections 字段、并
// 把路标历次出现压回旧版平铺字段的旧版文件（二进制版本号仍为 1），模拟
// 现网旧地图。
func writeLegacyV1File(t *testing.T, path string, st *mapState) {
	t.Helper()
	data, err := encodeFile(st)
	if err != nil {
		t.Fatal(err)
	}
	var raw map[string]any
	if err := json.Unmarshal(data[headerLen:len(data)-4], &raw); err != nil {
		t.Fatal(err)
	}
	delete(raw, "sources")
	delete(raw, "corrections")
	if lms, ok := raw["landmarks"].([]any); ok {
		for _, e := range lms {
			lm, ok := e.(map[string]any)
			if !ok {
				continue
			}
			occs, ok := lm["occurrences"].([]any)
			if !ok || len(occs) == 0 {
				continue
			}
			first, _ := occs[0].(map[string]any)
			lm["x"] = first["x"]
			lm["y"] = first["y"]
			lm["count"] = first["count"]
			delete(lm, "occurrences")
		}
	}
	payload, err := json.Marshal(raw)
	if err != nil {
		t.Fatal(err)
	}
	out := make([]byte, headerLen+len(payload)+4)
	copy(out[:headerLen], data[:headerLen])
	binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
	copy(out[headerLen:], payload)
	binary.BigEndian.PutUint32(out[len(out)-4:], crc32.ChecksumIEEE(out[:len(out)-4]))
	if err := os.WriteFile(path, out, 0o644); err != nil {
		t.Fatal(err)
	}
}

